const P=(k,x,y,n)=>({id:uid(),k,x,y,n}),A=(s,x1,y1,x2,y2)=>({s,x1,y1,x2,y2});
const row=(k,n,y,x0=.15,x1=.85)=>Array.from({length:n},(_,i)=>P(k,n>1?x0+(x1-x0)*i/(n-1):.5,y,i+1));
const GEN={
rondo:(a,d)=>{const p=[];for(let i=0;i<a;i++){const t=i/a*6.283-1.57;p.push(P('a',.5+.36*Math.cos(t),.5+.36*Math.sin(t),i+1))}p.push(...row('b',d,.5,.4,.6),P('ball',.5,.14));return{p,a:[A('pass',p[0].x,p[0].y,p[1].x,p[1].y),A('pass',p[1].x,p[1].y,p[2].x,p[2].y)]}},
sq:n=>{const p=[],a=[];for(let i=0;i<n;i++){const t=i/n*6.283-1.57,x=.5+.38*Math.cos(t),y=.5+.38*Math.sin(t);p.push(P('cone',x,y),P('a',x*.9+.05,y*.9+.05,i+1))}const q=p.filter(z=>z.k==='a');q.forEach((z,i)=>{const o=q[(i+1)%n];a.push(A('pass',z.x,z.y,o.x,o.y))});return{p,a}},
pairs:()=>({p:[P('a',.15,.5,1),P('a',.85,.5,2),P('cone',.3,.35),P('cone',.7,.35),P('ball',.2,.55)],a:[A('pass',.2,.45,.8,.45),A('run',.85,.6,.85,.75)]}),
slalom:n=>{const p=[],a=[];let px=.5,py=.92;p.push(P('a',px,py,1));for(let i=0;i<n;i++){const y=.8-i*(.65/n);p.push(P('cone',.5,y));const x=i%2?.32:.68;a.push(A('drib',px,py,x,y-.03));px=x;py=y-.03}return{p,a}},
shoot:()=>({p:[P('goal',.5,.06),P('a',.5,.8,1),P('a',.88,.45,2),P('cone',.3,.55),P('cone',.7,.55),P('ball',.88,.5)],a:[A('pass',.88,.45,.55,.72),A('shot',.5,.8,.5,.1)]}),
v1:()=>({p:[P('goal',.5,.05),P('goal',.5,.95),P('a',.5,.7,1),P('b',.5,.4,1),P('ball',.5,.75)],a:[A('drib',.5,.7,.35,.5),A('shot',.35,.5,.5,.1),A('run',.5,.4,.45,.55)]}),
game:n=>{const p=[P('goal',.5,.05),P('goal',.5,.95),...row('a',n,.7),...row('b',n,.3),P('ball',.5,.5)];return{p,a:[A('pass',p[2].x,p[2].y,p[3].x,p[3].y-.1)]}},
press:(a,b)=>{const p=[...row('a',a,.65),...row('b',b,.35),P('ball',.2,.7)];return{p,a:[A('pass',p[0].x,p[0].y,p[1].x,p[1].y),A('run',p[a].x,p[a].y,p[1].x,p[1].y-.05)]}},
keeper:()=>({p:[P('goal',.5,.06),P('g',.5,.15,1),P('a',.25,.6,1),P('a',.75,.6,2),P('ball',.25,.64)],a:[A('shot',.25,.6,.45,.1),A('shot',.75,.6,.55,.1)]}),
wave:n=>({p:[...row('a',n,.85),...row('cone',n,.2).map(z=>({...z,k:'cone'}))],a:row('a',n,.85).map(z=>A('run',z.x,.82,z.x,.25))}),
gates:()=>({p:[P('cone',.25,.5),P('cone',.35,.5),P('cone',.45,.3),P('cone',.55,.3),P('cone',.65,.5),P('cone',.75,.5),P('a',.5,.85,1),P('ball',.5,.8)],a:[A('drib',.5,.85,.3,.5),A('drib',.3,.5,.5,.3),A('drib',.5,.3,.7,.5)]}),
build:()=>({p:[P('g',.5,.9,1),P('a',.2,.72,2),P('a',.8,.72,3),P('a',.5,.55,4),P('b',.35,.5,1),P('b',.65,.5,2),P('ball',.5,.86)],a:[A('pass',.5,.9,.2,.72),A('pass',.2,.72,.5,.55),A('run',.8,.72,.85,.4)]})};
