function migrate(){S.forms=S.forms||{};S.seeded=S.seeded||[];S.drills.forEach(d=>{if(d.src==='seed'&&!d.dg&&DGMAP[d.name])d.dg=DGMAP[d.name]});
NEW.forEach(r=>{if(S.seeded.includes(r[0]))return;S.seeded.push(r[0]);S.drills.push({id:uid(),sid:r[0],name:r[1],cat:r[2],goal:r[3],min:r[4],np:r[5],space:r[6],level:r[7],equip:r[8],steps:r[9].split('|'),tips:r[10],mist:r[11],easy:r[12],hard:r[13],dg:r[14],src:'seed',fav:false,status:'جاهز',notes:'',board:'',cr:Date.now(),up:Date.now()})})}
function dgImg(d){if(!d.dg||!GEN[d.dg[0]])return'';const c=document.createElement('canvas');c.width=600;c.height=420;const c0=cx;cx=c.getContext('2d');cx.fillStyle='#2e8b3d';cx.fillRect(0,0,600,420);cx.strokeStyle='#fff';cx.lineWidth=4;cx.strokeRect(12,12,576,396);items(GEN[d.dg[0]](...d.dg.slice(1)),600,420);const u=c.toDataURL();cx=c0;return u}
const FORMS={'4-3-3':[1,4,3,3],'4-2-3-1':[1,4,2,3,1],'4-4-2':[1,4,4,2],'3-5-2':[1,3,5,2]};
function applyForm(n){if(!n)return;const f=FORMS[n]||S.forms[n];if(!f)return;snap();const fr=B.frames[fi];fr.p=fr.p.filter(i=>i.k!=='a'&&i.k!=='g');
if(typeof f[0]==='number'){const ys=f.map((_,i)=>.9-i*(.58/(f.length-1)));let k=0;f.forEach((c,i)=>{for(let j=0;j<c;j++)fr.p.push({id:uid(),k:i?'a':'g',x:(j+1)/(c+1),y:ys[i],n:++k})})}else f.forEach(q=>fr.p.push({...q,id:uid()}));draw()}
function saveForm(){const n=(prompt('اسم التشكيلة؟')||'').trim();if(!n)return;S.forms[n]=B.frames[fi].p.filter(i=>i.k==='a'||i.k==='g').map(({x,y,k,n})=>({x,y,k,n}));save();toast('تم حفظ التشكيلة');boardView()}
function linkD(id){if(!id)return;saveB();const d=S.drills.find(x=>x.id===id);d.board=B.id;save();toast('تم الربط بالتمرين')}
function arcD(id){const d=S.drills.find(x=>x.id===id);d.status=d.status==='مؤرشف'?'جاهز':'مؤرشف';save();dl()}
function pitchAlt(W,H){const pt=(B&&B.pt)||'full';if(pt==='full')return false;cx.fillStyle='#2e8b3d';cx.fillRect(0,0,W,H);cx.strokeStyle='#fff';cx.lineWidth=3;const m=W*.04;cx.strokeRect(m,m,W-2*m,H-2*m);if(pt==='half'){cx.strokeRect(W*.2,m,W*.6,H*.28);cx.strokeRect(W*.36,m,W*.28,H*.1);cx.beginPath();cx.arc(W/2,H-m,W*.13,Math.PI,0);cx.stroke()}else{cx.setLineDash([12,12]);cx.strokeRect(W*.18,H*.2,W*.64,H*.6);cx.setLineDash([])}return true}
const hs=s=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16)};
