const LOGO=()=>$('header img').src;
function showPrint(h){const p=$('#print');p.innerHTML=`<div class="pb"><button class="bt" onclick="window.print()">طباعة / حفظ PDF</button> <button class="bt s" onclick="$('#print').style.display='none'">إغلاق</button></div><div class="pg">${h}</div>`;p.style.display='block';p.scrollTop=0}
const pHead=t=>`<div class="ph"><img src="${LOGO()}" alt=""><div><h1>NOUN STAR U13</h1><div>${t}</div></div><div class="pd">Forza noun star<br>${new Date().toLocaleDateString('ar')}</div></div>`;
function boardImg(b,i){const c=document.createElement('canvas');c.width=600;c.height=840;const c0=cx,B0=B;cx=c.getContext('2d');B=b;pitch(600,840);items(b.frames[i||0],600,840);B=B0;cx=c0;return c.toDataURL()}
const boardBlock=b=>b.frames.slice(0,6).map((f,i)=>`<div class="blk"><h3>${esc(b.name)} — إطار ${i+1}</h3><img class="bi" alt="" src="${boardImg(b,i)}"></div>`).join('');
const drillBlock=d0=>drillBlock0(E(d0)),drillBlock0=d=>`<div class="blk"><h3>${esc(d.name)} <small>${d.min} د · ${esc(d.level)} · <bdi dir="ltr">${esc(d.np)}</bdi> لاعب</small></h3>${dgImgs(d).map(u=>`<img class="di" alt="" src="${u}">`).join('')}<p><b>الهدف:</b> ${esc(d.goal)}</p>${d.space?`<p><b>المساحة:</b> ${esc(d.space)}</p>`:''}<p><b>المعدات:</b> ${esc(d.equip)}</p><ol>${d.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><b>نقاط التدريب:</b> ${esc(d.tips)}</p><p><b>أخطاء شائعة:</b> ${esc(d.mist)}</p>${d.easy?`<p><b>تبسيط:</b> ${esc(d.easy)} — <b>تصعيد:</b> ${esc(d.hard)}</p>`:''}${d.safe?`<p><b>السلامة:</b> ${esc(d.safe)}</p>`:''}</div>`;
function printDrill(id){const d=S.drills.find(x=>x.id===id),b=S.boards.find(x=>x.id===d.board);closeM();showPrint(pHead('بطاقة تمرين')+drillBlock(d)+(b?boardBlock(b):''))}
