function printSession(id){const s=typeof id==='object'?id:S.sessions.find(x=>x.id===id),t=sum(s),df=t-s.total,at=Object.values(s.att||{}),n=k=>at.filter(x=>x===k).length;
showPrint(pHead('خطة حصة: '+esc(s.name))+`<table class="pt"><tr><td>التاريخ: ${esc(s.date)}</td><td>المدة المحددة: ${s.total} د</td><td>مجموع المراحل: ${t} د${df>0?` (يزيد ${df} د)`:''}</td></tr><tr><td colspan="3">الهدف: ${esc(s.goal||'—')}</td></tr></table><table class="pt"><tr><th>#</th><th>المرحلة</th><th>المدة</th><th>التمرين</th></tr>${s.ph.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${p.min} د</td><td>${esc((S.drills.find(d=>d.id===p.drill)||{}).name||'—')}</td></tr>`).join('')}</table>`+s.ph.map(p=>{const d=S.drills.find(x=>x.id===p.drill),b=S.boards.find(x=>x.id===p.board);return d||b?`<h2>${esc(p.name)} (${p.min} د)</h2>${p.note?`<p>ملاحظة المدرب: ${esc(p.note)}</p>`:''}`+(d?drillBlock(d):'')+(b?boardBlock(b):''):''}).join('')+`<div class="blk"><h3>الحضور والتقييم</h3><p>حاضر ${n('p')} · غائب ${n('a')} · متأخر ${n('l')} · مصاب ${n('i')} · معذور ${n('e')}</p><p>${esc(s.eval||'لا توجد ملاحظات')}</p></div>`)}
