const _m4=migrate;migrate=()=>{_m4();S.drills.forEach(d=>{if(d.src==='seed'&&!d.rev){const r=REV[d.sid]||REV[d.name];if(r)d.rev={v:2,date:'2026-10-13',fields:r.f,note:r.n}}});NEW5.forEach(r=>{if(S.seeded.includes(r[0]))return;S.seeded.push(r[0]);S.drills.push({id:uid(),sid:r[0],name:r[1],cat:r[2],goal:r[3],min:r[4],np:r[5],space:r[6],level:r[7],equip:r[8],steps:r[9].split('|'),tips:r[10],mist:r[11],easy:r[12],hard:r[13],dg:[r[14],r[15]],safe:r[16],src:'seed',fav:false,status:'جاهز',notes:'',board:'',cr:Date.now(),up:Date.now()})});S.drills.forEach(d=>{if(d.src==='seed'&&!d.rev){const r=REV[d.sid]||REV[d.name];if(r)d.rev={v:2,date:'2026-10-13',fields:r.f,note:r.n}}})};
dgImg=d=>dgImgs(d)[0]||'';
/* ---- Live training mode: READ-ONLY on library/DB. Writes only s.att and s.eval of the open session, and only on explicit save ---- */
let LV=null,LT=null,WL=null;
const mmss=t=>{const a=Math.abs(Math.round(t)),m=Math.floor(a/60),s=a%60;return(t<0?'+':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')};
const lvS=()=>S.sessions.find(x=>x.id===LV.sid),LVC=['','p','a','l','i','e'];
async function startLive(id){if(!LV){const o=lvLoad();if(o&&lvValid(o))return lvPrompt(o)}const s=S.sessions.find(x=>x.id===id);if(!s)return toast('احفظ الحصة أولًا');if(!s.ph.length)return toast('أضف مراحل للحصة أولًا');
LV={sid:id,i:0,left:s.ph[0].min*60,len:s.ph[0].min*60,run:false,tot:0,att:{},note:'',beeped:false,done:false,last:Date.now(),adj:{},rid:Math.random().toString(36).slice(2,8),seq:0,saveFail:false};try{WL=await navigator.wakeLock.request('screen')}catch(e){}clearInterval(LT);LT=setInterval(lvTick,500);$('#live').style.display='block';renderLive();lvPersist(true)}
function lvTick(){if(!LV)return;const n=Date.now(),dt=(n-LV.last)/1000;LV.last=n;if(LV.run&&!LV.done){LV.left-=dt;LV.tot+=dt;if(LV.left<=0&&!LV.beeped){LV.beeped=true;lvBeep()}}paintLive()}
function lvBeep(){try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator();o.connect(a.destination);o.frequency.value=880;o.start();setTimeout(()=>o.stop(),450)}catch(e){}try{navigator.vibrate&&navigator.vibrate([300,100,300])}catch(e){}}
function paintLive(){const c=$('#lvc');if(!c||LV.done)return;c.textContent=mmss(LV.left);c.style.color=LV.left<0?'#ff6b6b':LV.left<60?'#ffd400':'#fff';$('#lvb').style.width=Math.max(0,Math.min(100,100-LV.left/Math.max(LV.len,1)*100))+'%';$('#lvt').textContent='المنقضي '+mmss(LV.tot)+' / '+sum(lvS())+':00'}
function renderLive(){const s=lvS(),p=s.ph[LV.i],raw=S.drills.find(x=>x.id===p.drill),d=raw&&E(raw),nx=s.ph[LV.i+1],at=id=>LV.att[id]!==undefined?LV.att[id]:(s.att||{})[id]||'';
$('#live').innerHTML=`<div class="lvh"><b>${esc(s.name)}</b><span id="lvt" class="mut"></span><button class="bt m s" onclick="exitLive()">خروج مؤقت</button><button class="bt m r" onclick="endLive()">إنهاء</button></div><div id="lvw" class="card" style="background:#7a1f24;color:#fff;display:none">تعذّر حفظ حالة الحصة تلقائيًا في هذا المتصفح؛ لن تُستعاد بعد الإغلاق. استخدم «حفظ الحضور والملاحظات» وراقب الوقت يدويًا.</div><div class="lvn">المرحلة ${LV.i+1} من ${s.ph.length}: <b>${esc(p.name)}</b></div><div id="lvc" class="lvc"></div><div class="lvbar"><i id="lvb"></i></div>
<div class="row" style="justify-content:center;margin:8px 0"><button class="bt" onclick="lvGo(-1)">◀ السابق</button><button class="bt" id="lvp" onclick="lvTog()">${LV.run?'إيقاف مؤقت':'ابدأ'}</button><button class="bt" onclick="lvGo(1)">${nx?'التالي ▶':'إنهاء المراحل'}</button></div><div class="row" style="justify-content:center"><button class="bt m s" onclick="lvAdj(-1)">−1 د</button><button class="bt m s" onclick="lvAdj(1)">+1 د</button></div>
${nx?`<div class="lvn">التالي: ${esc(nx.name)} (${nx.min} د)</div>`:''}${p.note?`<div class="card lvk">ملاحظة المدرب: ${esc(p.note)}</div>`:''}
${d?`<div class="card lvk"><h3>${esc(d.name)}</h3>${dgImgs(d,1).map(u=>`<img alt="" src="${u}" style="width:100%;border-radius:10px;margin-bottom:4px">`).join('')}<p><b>الهدف:</b> ${esc(d.goal)}</p><p><b>المساحة:</b> ${esc(d.space||'—')} · <b>المعدات:</b> ${esc(d.equip)}</p><ol>${d.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p><b>نقاط التدريب:</b> ${esc(d.tips)}</p><p><b>أخطاء شائعة:</b> ${esc(d.mist)}</p>${d.easy?`<p><b>تبسيط:</b> ${esc(d.easy)} — <b>تصعيد:</b> ${esc(d.hard)}</p>`:''}${d.safe?`<p><b>السلامة:</b> ${esc(d.safe)}</p>`:''}</div>`:'<div class="mut" style="text-align:center">لا يوجد تمرين مرتبط بهذه المرحلة</div>'}
<details class="card lvk"><summary>الحضور السريع</summary>${S.players.map(pl=>`<div class="row" style="margin:4px 0"><span style="flex:1">${esc(pl.name)}</span><button class="bt m s" id="la${pl.id}" onclick="lvAtt('${pl.id}')">${ST[at(pl.id)]||'—'}</button></div>`).join('')||'<div class="mut">لا يوجد لاعبون</div>'}</details>
<details class="card lvk"><summary>ملاحظات الحصة</summary><textarea rows="3" oninput="LV.note=this.value;lvDebounce()">${esc(LV.note)}</textarea></details><button class="bt" onclick="lvSave()">حفظ الحضور والملاحظات في الحصة</button>`;paintLive()}
function lvTog(){LV.run=!LV.run;LV.last=Date.now();$('#lvp').textContent=LV.run?'إيقاف مؤقت':'ابدأ';lvPersist(true)}
function lvAdj(d){LV.left+=d*60;LV.len=Math.max(60,LV.len+d*60);LV.adj[LV.i]=(LV.adj[LV.i]||0)+d*60;if(LV.left>0)LV.beeped=false;paintLive();lvPersist(true)}
function lvGo(d){const s=lvS(),n=LV.i+d;if(n<0)return;if(n>=s.ph.length){LV.done=true;LV.run=false;lvDone();lvPersist(true);return}
LV.i=n;LV.left=s.ph[n].min*60+(LV.adj[n]||0);LV.len=LV.left;LV.beeped=false;renderLive();lvPersist(true)}
function lvDone(){const s=lvS(),pl=sum(s);$('#live').innerHTML=`<div class="lvh"><b>${esc(s.name)}</b></div><div class="lvn">انتهت الحصة</div><div class="lvc" style="font-size:60px">${mmss(LV.tot)}</div><div class="lvn">المخطط ${pl}:00 · الفعلي ${mmss(LV.tot)}</div><div class="row" style="justify-content:center"><button class="bt" onclick="lvSave()">حفظ الحضور والملاحظات</button><button class="bt s" onclick="endLive()">إنهاء الحصة</button></div><details class="card lvk" open><summary>ملاحظات الحصة</summary><textarea rows="3" oninput="LV.note=this.value;lvDebounce()">${esc(LV.note)}</textarea></details>`}
function lvAtt(id){const s=lvS(),cur=LV.att[id]!==undefined?LV.att[id]:(s.att||{})[id]||'',n=LVC[(LVC.indexOf(cur)+1)%LVC.length];LV.att[id]=n;$('#la'+id).textContent=ST[n]||'—';lvPersist(true)}
function lvSave(skipToast){const s=lvS();Object.entries(LV.att).forEach(([k,v])=>{s.att=s.att||{};if(v)s.att[k]=v;else delete s.att[k]});if(LV.note.trim()){const tag='[تدريب مباشر '+new Date().toLocaleDateString('ar')+' #'+LV.rid+LV.seq+']';if(!(s.eval||'').includes(tag))s.eval=(s.eval?s.eval+'\n':'')+tag+' '+LV.note.trim();LV.seq++;LV.note=''}LV.att={};save();if(!skipToast)toast('تم الحفظ في الحصة');if(LV.done){lvClear()}else lvPersist(true)}
function exitLive(){if(LV.saveFail&&!confirm('تعذّر الحفظ التلقائي؛ الخروج سيفقد حالة الحصة وأي تغييرات غير محفوظة. متابعة؟'))return;LV.run=false;lvPersist(true);const keep=!LV.saveFail;clearInterval(LT);clearTimeout(lvDeb);try{WL&&WL.release()}catch(e){}WL=null;LV=null;$('#live').style.display='none';$('#live').innerHTML='';if(keep&&$('#main'))go(view)}
/* ---- live resume: autosave of the running session in localStorage key nsu13_live (NOT in the IndexedDB/S schema; not part of backups) ---- */
const LK='nsu13_live',LV_TTL=12*3600*1e3;let lvLast='',lvDeb=null;
function lvSnap(){return{v:1,sid:LV.sid,i:LV.i,run:LV.run,left:LV.left,len:LV.len,tot:LV.tot,adj:LV.adj,att:LV.att,note:LV.note,done:LV.done,rid:LV.rid,seq:LV.seq,beeped:LV.beeped,ref:Date.now()}}
function lvPersist(force){if(!LV)return;try{const sn=lvSnap(),k=JSON.stringify({...sn,ref:0});if(!force&&k===lvLast)return;localStorage.setItem(LK,JSON.stringify(sn));lvLast=k;LV.saveFail=false}catch(e){LV.saveFail=true}lvWarn()}
function lvWarn(){const w=$('#lvw');if(w)w.style.display=LV&&LV.saveFail?'block':'none'}
const lvDebounce=()=>{clearTimeout(lvDeb);lvDeb=setTimeout(()=>lvPersist(),800)};
function lvLoad(){let r=null;try{r=localStorage.getItem(LK)}catch(e){return null}if(!r)return null;try{const st=JSON.parse(r);if(st.v!==1||!st.sid||typeof st.left!=='number')throw 0;return st}catch(e){try{localStorage.removeItem(LK)}catch(_){}toast('حالة الحصة المحفوظة تالفة وتم تجاهلها');return null}}
function lvDrop(){try{localStorage.removeItem(LK)}catch(e){}lvLast=''}
function lvValid(st){const s=S.sessions.find(x=>x.id===st.sid);if(!s||st.i>=s.ph.length){lvDrop();toast('حُذفت حالة حصة لم تعد موجودة');return false}if(Date.now()-st.ref>LV_TTL){lvDrop();toast('حُذفت حالة حصة قديمة (أكثر من 12 ساعة)');return false}return true}
const lvEl=st=>st.run&&!st.done?Math.max(0,(Date.now()-st.ref)/1000):0;
function lvPending(o){return Object.keys(o.att||{}).length||(o.note||'').trim()}
function lvPrompt(st){const s=S.sessions.find(x=>x.id===st.sid),l=st.left-lvEl(st);modal(`<h3>حصة غير منتهية</h3><p><b>${esc(s.name)}</b><br>المرحلة ${st.i+1} من ${s.ph.length}: ${esc(s.ph[st.i].name)}<br>${st.done?'انتهت المراحل ولم تُحفظ النتيجة':(st.run?'المؤقت كان يعمل — ':'المؤقت متوقف — ')+(l<0?'تجاوز المدة بـ '+mmss(-l):'المتبقي '+mmss(l))}${lvPending(st)?'<br><span class="bad">توجد بيانات حضور/ملاحظات غير محفوظة</span>':''}</p><div class="row"><button class="bt" onclick="closeM();lvResume()">استئناف الحصة</button><button class="bt r" onclick="closeM();endLive(1)">إنهاء الحصة</button><button class="bt s" onclick="closeM()">لاحقًا</button></div>`)}
function lvBuild(st){const el=lvEl(st),l=st.left-el;LV={sid:st.sid,i:st.i,run:st.run&&!st.done,left:l,len:st.len,tot:st.tot+el,adj:st.adj||{},att:st.att||{},note:st.note||'',done:!!st.done,rid:st.rid,seq:st.seq||0,beeped:!!st.beeped||l<0,last:Date.now(),saveFail:false}}
async function lvResume(){const st=lvLoad();if(!st||!lvValid(st))return;lvBuild(st);try{WL=await navigator.wakeLock.request('screen')}catch(e){}clearInterval(LT);LT=setInterval(lvTick,500);$('#live').style.display='block';LV.done?lvDone():renderLive();lvPersist(true)}
function checkResume(){if(LV||$('#lock').style.display==='flex')return;const st=lvLoad();if(st&&lvValid(st))lvPrompt(st)}
const lvBanner=()=>{const st=LV?null:lvLoad();const s=st&&S.sessions.find(x=>x.id===st.sid);return s&&Date.now()-st.ref<LV_TTL?`<div class="card" style="border-color:var(--b)"><b>حصة جارية: ${esc(s.name)}</b> <button class="bt m" onclick="lvPrompt(lvLoad())">استئناف / إنهاء</button></div>`:''};
function lvClear(){clearInterval(LT);clearTimeout(lvDeb);try{WL&&WL.release()}catch(e){}WL=null;LV=null;lvDrop();$('#live').style.display='none';$('#live').innerHTML=''}
function endLive(fromPrompt){if(fromPrompt&&!LV){const st=lvLoad();if(!st)return;lvBuild(st)}if(!confirm('إنهاء الحصة نهائيًا وحذف حالة الاستئناف؟'))return;if(lvPending(LV)&&confirm('توجد بيانات حضور/ملاحظات غير محفوظة. حفظها في الحصة قبل الإنهاء؟ (موافق = حفظ، إلغاء = تجاهل)'))lvSave(1);lvClear()}
