/* ---- drills ---- */
let fq='',fc='',ff=false,fa=false;
let fl='',fd='',fn='',fp='',ft='',so='';
function drills(){const sel=(v,x,o,ph)=>`<select style="flex:1;min-width:30%" onchange="${v}=this.value;dl()"><option value="">${ph}</option>${o.map(t=>`<option ${t===x?'selected':''}>${t}</option>`).join('')}</select>`;
$('#main').innerHTML=`<input id="q" placeholder="ابحث بالاسم أو الهدف أو الأدوات…" value="${esc(fq)}" oninput="fq=this.value;dl()"><div class="row">${sel('fc',fc,CATS,'كل المجالات')}${sel('fl',fl,['سهل','متوسط','متقدم'],'المستوى')}${sel('fp',fp,['إحماء','رئيسي','تهدئة'],'المرحلة')}${sel('ft',ft,['فني','تكتيكي','بدني','لعب'],'النوع')}${sel('fd',fd,['≤10','11-15','16-20','>20'],'المدة (د)')}${sel('so',so,['الاسم','الأقصر','الأطول','الأحدث'],'ترتيب')}<input style="flex:1;min-width:30%" type="number" placeholder="عدد اللاعبين" value="${fn}" oninput="fn=this.value;dl()"></div><div class="row"><label><input type="checkbox" style="width:auto" ${ff?'checked':''} onchange="ff=this.checked;dl()"> مفضلة</label><label><input type="checkbox" style="width:auto" ${fa?'checked':''} onchange="fa=this.checked;dl()"> مؤرشفة</label><button class="bt m" onclick="editDrill()">+ تمرين جديد</button></div><div class="mut" id="cnt"></div><div id="dl" style="margin-top:6px"></div>`;dl()}
function dl(){const l=S.drills.filter(d=>(fa?d.status==='مؤرشف':d.status!=='مؤرشف')&&(!fc||d.cat===fc)&&(!fl||d.level===fl)&&(!fp||phs(d)===fp)&&(!ft||tys(d)===ft)&&(!fd||dm(d)===fd)&&(!fn||(npr(d)[0]<=+fn&&+fn<=npr(d)[1]))&&(!ff||d.fav)&&(!fq||(d.name+d.goal+d.cat+d.equip+d.level+d.space+d.np).includes(fq)));
if(so==='الاسم')l.sort((a,b)=>a.name.localeCompare(b.name,'ar'));if(so==='الأقصر')l.sort((a,b)=>a.min-b.min);if(so==='الأطول')l.sort((a,b)=>b.min-a.min);if(so==='الأحدث')l.sort((a,b)=>b.cr-a.cr);
$('#cnt').textContent=`النتائج: ${l.length} من ${S.drills.length} تمرين`;
$('#dl').innerHTML=l.map(d=>`<div class="card"><div class="row"><b style="flex:1">${d.fav?'★ ':''}${esc(d.name)}</b><span class="tag">${d.min} د</span></div><div class="mut">${esc(d.cat)} · ${tys(d)} · ${esc(d.level)} · <bdi dir="ltr">${esc(d.np)}</bdi> لاعب</div><div class="row" style="margin-top:6px"><button class="bt m s" onclick="viewDrill('${d.id}')">عرض</button><button class="bt m s" onclick="editDrill('${d.id}')">تعديل</button><button class="bt m s" onclick="favD('${d.id}')">★</button><button class="bt m s" onclick="copyD('${d.id}')">نسخ</button><button class="bt m s" onclick="arcD('${d.id}')">${d.status==='مؤرشف'?'استرجاع':'أرشفة'}</button><button class="bt m r" onclick="delD('${d.id}')">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد تمارين مطابقة</div>'}
function viewDrill(id,orig){const d0=S.drills.find(x=>x.id===id),d=orig?d0:E(d0);modal(`<h3>${esc(d.name)}</h3>${d0.rev?`<div class="card"><b>نسخة محسّنة v${d0.rev.v}</b> — ${esc(d0.rev.note)}<br><button class="bt m s" onclick="viewDrill('${d0.id}',${orig?0:1})">${orig?'عرض المحسّنة':'عرض الأصل'}</button></div>`:''}<div class="mut">${esc(d.cat)} · ${esc(d.level)} · ${d.min} د · <bdi dir="ltr">${esc(d.np)}</bdi> لاعب</div>${dgImgs(d,1).map(u=>`<img alt="رسم التمرين" src="${u}" style="width:100%;border-radius:10px;margin-bottom:4px">`).join('')}<p><b>الهدف:</b> ${esc(d.goal)}</p>${d.space?`<p><b>المساحة:</b> ${esc(d.space)}</p>`:''}<p><b>المعدات:</b> ${esc(d.equip)}</p><b>الخطوات:</b><ol>${d.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><b>نقاط التدريب:</b> ${esc(d.tips)}</p><p><b>أخطاء شائعة:</b> ${esc(d.mist)}</p>${d.easy?`<p><b>تبسيط:</b> ${esc(d.easy)}</p>`:''}${d.hard?`<p><b>زيادة الصعوبة:</b> ${esc(d.hard)}</p>`:''}${d.safe?`<p><b>السلامة:</b> ${esc(d.safe)}</p>`:''}${d.notes?`<p><b>ملاحظاتي:</b> ${esc(d.notes)}</p>`:''}<p class="mut">${d.src==='seed'?'تمرين أنشأه التطبيق (غير مراجَع من جهة رسمية)':'تمرين من إعداد المدرب'}</p><div class="row">${d.board?`<button class="bt" onclick="closeM();openBoard('${d.board}')">فتح اللوحة</button>`:''}<button class="bt s" onclick="printDrill('${d.id}')">طباعة / PDF</button><button class="bt s" onclick="closeM()">إغلاق</button></div>`)}
