const pos=e=>{const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}};
const hit=(f,q)=>[...f.p].reverse().find(i=>Math.hypot(i.x-q.x,(i.y-q.y)*1.4)<.075);
function snap(){hist.push(JSON.stringify(B.frames));if(hist.length>60)hist.shift();redo=[]}
function undo(){if(!hist.length)return;redo.push(JSON.stringify(B.frames));B.frames=JSON.parse(hist.pop());fi=Math.min(fi,B.frames.length-1);boardView()}
function doRedo(){if(!redo.length)return;hist.push(JSON.stringify(B.frames));B.frames=JSON.parse(redo.pop());fi=Math.min(fi,B.frames.length-1);boardView()}
function pd(e){e.preventDefault();if(playing)return;const f=B.frames[fi],q=pos(e);cv.setPointerCapture(e.pointerId);const h=hit(f,q);
if(tool==='del'){snap();if(h)f.p=f.p.filter(i=>i!==h);else{const k=f.a.findIndex(a=>dseg(q,a)<.03);if(k>=0)f.a.splice(k,1)}draw();return}
if(h&&(tool==='move'||tool[0]==='p'||EQ.includes(tool))){snap();drag=h;return}
if(['pass','run','drib','shot'].includes(tool)){tmp={x1:q.x,y1:q.y,x2:q.x,y2:q.y,s:tool};return}
if(tool[0]==='p'||EQ.includes(tool)){snap();const k=tool==='pa'?'a':tool==='pb'?'b':tool==='pg'?'g':tool;f.p.push({id:uid(),x:q.x,y:q.y,k,n:f.p.filter(i=>i.k===k).length+1});draw()}}
function pm(e){const q=pos(e);if(drag){drag.x=Math.max(0,Math.min(1,q.x));drag.y=Math.max(0,Math.min(1,q.y));draw()}else if(tmp){tmp.x2=q.x;tmp.y2=q.y;draw()}}
function pu(){if(tmp){if(Math.hypot(tmp.x2-tmp.x1,(tmp.y2-tmp.y1)*1.4)>.04){snap();B.frames[fi].a.push(tmp)}tmp=null;draw()}drag=null}
function dseg(p,a){const dx=a.x2-a.x1,dy=a.y2-a.y1,l=dx*dx+dy*dy||1e-9,t=Math.max(0,Math.min(1,((p.x-a.x1)*dx+(p.y-a.y1)*dy)/l));return Math.hypot(p.x-a.x1-t*dx,(p.y-a.y1-t*dy)*1.4)}
function pitch(W,H){if(pitchAlt(W,H))return;cx.fillStyle='#2e8b3d';cx.fillRect(0,0,W,H);cx.fillStyle='#ffffff14';for(let i=0;i<8;i+=2)cx.fillRect(0,i*H/8,W,H/8);cx.strokeStyle='#fff';cx.lineWidth=3;const m=W*.04;cx.strokeRect(m,m,W-2*m,H-2*m);cx.beginPath();cx.moveTo(m,H/2);cx.lineTo(W-m,H/2);cx.stroke();cx.beginPath();cx.arc(W/2,H/2,W*.13,0,7);cx.stroke();
for(const y of[m,H-m]){const s=y<H/2?1:-1;cx.strokeRect(W*.2,s>0?m:H-m-H*.15,W*.6,H*.15);cx.strokeRect(W*.36,s>0?m:H-m-H*.06,W*.28,H*.06)}}
function items(f,W,H){const sc=W/340;f.a.forEach(a=>arrow(a,W,H));f.p.forEach(i=>{const x=i.x*W,y=i.y*H,r=14*sc;
if(i.k==='cone'){cx.fillStyle='#ff8c00';cx.beginPath();cx.moveTo(x,y-r);cx.lineTo(x+r*.8,y+r*.7);cx.lineTo(x-r*.8,y+r*.7);cx.fill();return}
if(i.k==='goal'){cx.fillStyle='#ffffff66';cx.strokeStyle='#fff';cx.lineWidth=3;cx.fillRect(x-r*1.6,y-r*.5,r*3.2,r),cx.strokeRect(x-r*1.6,y-r*.5,r*3.2,r);return}if(i.k==='disc'){cx.fillStyle='#ffd400';cx.beginPath();cx.arc(x,y,r*.4,0,7);cx.fill();return}if(i.k==='ball'){cx.fillStyle='#fff';cx.strokeStyle='#000';cx.lineWidth=2;cx.beginPath();cx.arc(x,y,r*.6,0,7);cx.fill();cx.stroke();return}
cx.fillStyle={a:'#172DC4',b:'#d62828',g:'#ffd400'}[i.k];cx.strokeStyle='#fff';cx.lineWidth=3;cx.beginPath();cx.arc(x,y,r,0,7);cx.fill();cx.stroke();cx.fillStyle=i.k==='g'?'#000':'#fff';cx.font=`bold ${13*sc}px Tahoma`;cx.textAlign='center';cx.textBaseline='middle';cx.fillText(i.n,x,y+1)})}
function arrow(a,W,H){const x1=a.x1*W,y1=a.y1*H,x2=a.x2*W,y2=a.y2*H,st={pass:['#fff',[],4],run:['#ffd400',[14,10],4],drib:['#7fe3ff',[3,9],5],shot:['#ff4d4d',[],7]}[a.s];cx.strokeStyle=cx.fillStyle=st[0];cx.lineWidth=st[2];cx.setLineDash(st[1]);cx.beginPath();cx.moveTo(x1,y1);cx.lineTo(x2,y2);cx.stroke();cx.setLineDash([]);const t=Math.atan2(y2-y1,x2-x1),h=18;cx.beginPath();cx.moveTo(x2,y2);cx.lineTo(x2-h*Math.cos(t-.4),y2-h*Math.sin(t-.4));cx.lineTo(x2-h*Math.cos(t+.4),y2-h*Math.sin(t+.4));cx.fill()}
function draw(f){if(!cv)return;const W=cv.width,H=cv.height;pitch(W,H);items(f||B.frames[fi],W,H);if(tmp)arrow(tmp,W,H)}
function mv(d){const n=fi+d;if(n>=0&&n<B.frames.length){fi=n;boardView()}}
function addFrame(){snap();const c=JSON.parse(JSON.stringify(B.frames[fi]));c.a=[];B.frames.splice(fi+1,0,c);fi++;boardView()}
function delFrame(){if(B.frames.length<2)return toast('لا يمكن حذف الإطار الوحيد');if(!confirm('حذف هذا الإطار؟'))return;snap();B.frames.splice(fi,1);fi=Math.max(0,fi-1);boardView()}
function play(){if(playing){playing=false;return boardView()}if(B.frames.length<2)return toast('أضف إطارين على الأقل');playing=true;fi=0;boardView();let k=0,t0=performance.now();
const step=now=>{if(!playing)return;const a=B.frames[k],b=B.frames[k+1];if(!b){playing=false;fi=B.frames.length-1;return boardView()}const t=Math.min(1,(now-t0)*spd/1500);
draw({a:t>.5?b.a:a.a,p:b.p.map(o=>{const s=a.p.find(i=>i.id===o.id)||o;return{...o,x:s.x+(o.x-s.x)*t,y:s.y+(o.y-s.y)*t}})});
if(t>=1){k++;fi=k;t0=now;}requestAnimationFrame(step)};requestAnimationFrame(step)}
function saveB(copy){if(copy){B=JSON.parse(JSON.stringify(B));B.id=uid();B.name+=' (نسخة)'}const i=S.boards.findIndex(b=>b.id===B.id);const c=JSON.parse(JSON.stringify(B));if(i>=0)S.boards[i]=c;else S.boards.unshift(c);save();toast('تم حفظ اللوحة');boardView()}
function openBoard(id){B=JSON.parse(JSON.stringify(S.boards.find(b=>b.id===id)));fi=0;hist=[];redo=[];go('board')}
function delB(id){if(confirm('حذف اللوحة؟')){S.boards=S.boards.filter(b=>b.id!==id);save();boardView()}}
function exportPNG(){const W=cv.width,H=cv.height,o=document.createElement('canvas');o.width=W;o.height=H+90;const c0=cx;cx=o.getContext('2d');cx.fillStyle='#050505';cx.fillRect(0,0,W,o.height);cx.save();cx.translate(0,90);pitch(W,H);items(B.frames[fi],W,H);cx.restore();cx.drawImage(logoImg,W-80,5,76,76);cx.fillStyle='#fff';cx.font='bold 34px Tahoma';cx.textAlign='right';cx.textBaseline='middle';cx.direction='rtl';cx.fillText('NOUN STAR U13 · '+B.name,W-100,45);const u=o.toDataURL('image/png');cx=c0;
modal(`<img src="${u}" style="width:100%"><p class="mut">اضغط مطولًا على الصورة لحفظها.</p><button class="bt s" onclick="closeM()">إغلاق</button>`)}
/* ---- sessions ---- */
let ES=null;
function newSess(){ES={id:'',name:'حصة جديدة',date:new Date().toISOString().slice(0,10),total:90,goal:'',ph:[{id:uid(),name:'الإحماء',min:15,drill:''},{id:uid(),name:'التمرين الفني',min:25,drill:''},{id:uid(),name:'المباراة المصغرة',min:30,drill:''}],att:{},eval:''};go('sedit')}
function sess(){$('#main').innerHTML=`<button class="bt" onclick="newSess()">+ حصة جديدة</button><div style="margin-top:10px">${[...S.sessions].sort((a,b)=>a.date<b.date?1:-1).map(s=>`<div class="card"><b>${esc(s.name)}</b> <span class="mut">${s.date} · ${sum(s)}/${s.total} د</span><div class="row" style="margin-top:6px"><button class="bt m s" onclick="editS('${s.id}')">فتح</button><button class="bt m s" onclick="cpS('${s.id}')">نسخ</button><button class="bt m" onclick="startLive('${s.id}')">تدريب مباشر</button><button class="bt m s" onclick="printSession('${s.id}')">طباعة / PDF</button><button class="bt m r" onclick="delS('${s.id}')">حذف</button></div></div>`).join('')||'<div class="empty">لا توجد حصص. أنشئ أول حصة.</div>'}</div>`}
function editS(id){ES=JSON.parse(JSON.stringify(S.sessions.find(s=>s.id===id)));go('sedit')}
function cpS(id){const c=JSON.parse(JSON.stringify(S.sessions.find(s=>s.id===id)));c.id=uid();c.name+=' (نسخة)';c.att={};c.eval='';S.sessions.unshift(c);save();sess()}
function delS(id){if(confirm('حذف الحصة؟')){S.sessions=S.sessions.filter(s=>s.id!==id);save();sess()}}
function sedit(){const t=sum(ES),df=t-ES.total;
$('#main').innerHTML=`<label>اسم الحصة</label><input value="${esc(ES.name)}" oninput="ES.name=this.value"><div class="g"><div><label>التاريخ</label><input type="date" value="${ES.date}" oninput="ES.date=this.value"></div><div><label>المدة (د)</label><input type="number" value="${ES.total}" oninput="ES.total=+this.value;sedit()"></div></div><label>الهدف</label><input value="${esc(ES.goal)}" oninput="ES.goal=this.value">
<div class="card"><b>المراحل</b> <span class="${df>0?'bad':'ok'}">المجموع ${t} د ${df>0?`(يزيد ${df} د)`:df<0?`(متبقي ${-df} د)`:'✓'}</span>${ES.ph.map((p,i)=>`<div class="card"><div class="row"><input style="flex:2;margin:0" value="${esc(p.name)}" oninput="ES.ph[${i}].name=this.value"><input style="flex:1;margin:0" type="number" value="${p.min}" oninput="ES.ph[${i}].min=+this.value" onchange="sedit()"></div><select onchange="ES.ph[${i}].drill=this.value"><option value="">— تمرين من المكتبة —</option>${S.drills.map(d=>`<option value="${d.id}" ${d.id===p.drill?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select onchange="ES.ph[${i}].board=this.value"><option value="">— لوحة تكتيكية —</option>${S.boards.map(b=>`<option value="${b.id}" ${b.id===p.board?'selected':''}>${esc(b.name)}</option>`).join('')}</select><input placeholder="ملاحظات المدرب لهذه المرحلة" value="${esc(p.note||'')}" oninput="ES.ph[${i}].note=this.value"><div class="row"><button class="bt m s" onclick="mvP(${i},-1)">▲</button><button class="bt m s" onclick="mvP(${i},1)">▼</button><button class="bt m s" onclick="ES.ph.splice(${i+1},0,{...ES.ph[${i}],id:uid()});sedit()">تكرار</button><button class="bt m r" onclick="ES.ph.splice(${i},1);sedit()">حذف</button></div></div>`).join('')}<button class="bt m s" onclick="ES.ph.push({id:uid(),name:'مرحلة',min:10,drill:''});sedit()">+ مرحلة</button></div>
<div class="card"><b>الحضور</b>${S.players.map(p=>`<div class="row" style="margin:4px 0"><span style="flex:1">${esc(p.name)}</span><select style="width:110px;margin:0" onchange="ES.att['${p.id}']=this.value"><option value="">—</option>${Object.entries(ST).map(([k,v])=>`<option value="${k}" ${ES.att[p.id]===k?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')||'<div class="mut">أضف لاعبين أولًا</div>'}</div>
<label>تقييم الحصة (الأهداف، التفاعل، الصعوبات، توصية للقادمة)</label><textarea rows="4" oninput="ES.eval=this.value">${esc(ES.eval)}</textarea><div class="row"><button class="bt" onclick="saveS()">حفظ الحصة</button><button class="bt s" onclick="ES.id?startLive(ES.id):toast('احفظ الحصة أولًا')">تدريب مباشر</button><button class="bt s" onclick="printSession(ES)">طباعة / PDF</button><button class="bt s" onclick="go('sess')">رجوع</button></div>`}
function mvP(i,d){const j=i+d;if(j<0||j>=ES.ph.length)return;[ES.ph[i],ES.ph[j]]=[ES.ph[j],ES.ph[i]];sedit()}
function saveS(){if(!ES.id){ES.id=uid();S.sessions.unshift(ES)}else{const i=S.sessions.findIndex(s=>s.id===ES.id);S.sessions[i]=ES}save();toast('تم حفظ الحصة');go('sess')}
/* ---- players ---- */
function players(){$('#main').innerHTML=`<div class="row"><button class="bt" onclick="editP()">+ لاعب</button><button class="bt s" onclick="impP()">استيراد CSV</button></div><div style="margin-top:10px">${S.players.map(p=>`<div class="card row"><b style="flex:1">${p.num?'#'+p.num+' ':''}${esc(p.name)}</b><span class="tag">${esc(p.pos||'')}</span><button class="bt m s" onclick="editP('${p.id}')">تعديل</button><button class="bt m r" onclick="delP('${p.id}')">حذف</button></div>`).join('')||'<div class="empty">لا يوجد لاعبون بعد</div>'}</div>`}
function editP(id){const p=S.players.find(x=>x.id===id)||{id:'',name:'',num:'',pos:'',foot:'',status:'نشط',notes:''};window._p=p;modal(`<h3>لاعب</h3><label>الاسم</label><input id="p1" value="${esc(p.name)}"><div class="g"><div><label>رقم القميص</label><input id="p2" type="number" value="${p.num}"></div><div><label>المركز</label><input id="p3" value="${esc(p.pos)}"></div></div><label>الحالة</label><select id="p4">${['نشط','مصاب','متوقف مؤقتًا'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select><label>ملاحظات</label><input id="p5" value="${esc(p.notes)}"><div class="row"><button class="bt" onclick="saveP()">حفظ</button><button class="bt s" onclick="closeM()">إلغاء</button></div>`)}
function saveP(){const p=window._p,v=i=>$('#p'+i).value;if(!v(1).trim())return toast('اكتب الاسم');Object.assign(p,{name:v(1).trim(),num:v(2),pos:v(3),status:v(4),notes:v(5)});if(!p.id){p.id=uid();S.players.push(p)}save();closeM();players()}
function delP(id){if(confirm('حذف اللاعب؟')){S.players=S.players.filter(p=>p.id!==id);save();players()}}
function impP(){modal(`<h3>استيراد لاعبين (CSV)</h3><p class="mut">الأعمدة بالترتيب: الاسم، الرقم، المركز. ألصق النص أو اختر ملف CSV. (ملفات XLSX غير مدعومة؛ احفظها كـ CSV أولًا.)</p><input type="file" accept=".csv,.txt" onchange="const r=new FileReader();r.onload=()=>{$('#csv').value=r.result;prevP()};r.readAsText(this.files[0])"><textarea id="csv" rows="5" oninput="prevP()"></textarea><div id="pv"></div><div class="row"><button class="bt" id="okI" onclick="doImp()" disabled>استيراد</button><button class="bt s" onclick="closeM()">إلغاء</button></div>`)}
let IMP=[];
function prevP(){const rows=$('#csv').value.split(/\r?\n/).map(l=>l.split(/[,;\t]/).map(x=>x.trim())).filter(r=>r[0]);if(rows.length&&rows[0][1]&&isNaN(rows[0][1]))rows.shift();let bad=0,dup=0;IMP=[];
rows.forEach(r=>{if(!r[0]||(r[1]&&isNaN(r[1]))){bad++;return}if(S.players.some(p=>p.name===r[0]||(r[1]&&p.num===r[1]))||IMP.some(p=>p.name===r[0])){dup++;return}IMP.push({id:uid(),name:r[0],num:r[1]||'',pos:r[2]||'',status:'نشط',notes:''})});
$('#pv').innerHTML=`<p>سيُضاف <b>${IMP.length}</b> · مكرر (يُتجاهل): ${dup} · خطأ: <span class="bad">${bad}</span></p>`+IMP.slice(0,5).map(p=>`<div class="mut">${esc(p.name)} #${p.num}</div>`).join('');$('#okI').disabled=!IMP.length}
function doImp(){S.players.push(...IMP);save();closeM();toast('تم استيراد '+IMP.length);players()}
/* ---- more: backup, security, settings ---- */
function more(){$('#main').innerHTML=`<div class="card"><h3>المظهر</h3><button class="bt s" onclick="S.settings.theme=S.settings.theme==='dark'?'light':'dark';theme();save();">تبديل الفاتح / الداكن</button></div>
<div class="card"><h3>قفل PIN</h3><p class="mut">يخفي الواجهة فقط ولا يشفّر بيانات المتصفح؛ ليس حماية كاملة للجهاز.</p><button class="bt s" onclick="setPin()">${S.settings.pin?'تغيير PIN':'تفعيل PIN'}</button> ${S.settings.pin?'<button class="bt s" onclick="delete S.settings.pin;save();more()">إلغاء القفل</button>':''}</div>
<div class="card"><h3>النسخ الاحتياطي</h3><p class="mut">كل البيانات محلية في هذا المتصفح، ولا تُرسل لأي خادم.</p><button class="bt" onclick="expB()">إنشاء نسخة (JSON)</button> <button class="bt s" onclick="impB()">استعادة نسخة</button></div>
<div class="card"><h3>حذف كل البيانات</h3><button class="bt r" onclick="if(confirm('سيتم حذف كل البيانات نهائيًا. متابعة؟')){S={drills:[],boards:[],players:[],sessions:[],settings:S.settings,v:1};seed();migrate();save();go('home')}">حذف وإعادة ضبط</button></div>`}
function theme(){document.documentElement.dataset.theme=S.settings.theme||'light'}
async function sha(t){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('ns13'+t));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function setPin(){modal(`<h3>رمز PIN</h3><input id="np" type="password" inputmode="numeric" placeholder="4 أرقام على الأقل"><div class="row"><button class="bt" onclick="savePin()">حفظ</button><button class="bt s" onclick="closeM()">إلغاء</button></div>`)}
async function savePin(){const v=$('#np').value;if(!/^\d{4,}$/.test(v))return toast('أدخل 4 أرقام على الأقل');S.settings.pin=await sha(v);save();closeM();more()}
async function unlock(){if(await sha($('#pin').value)===S.settings.pin){$('#lock').style.display='none';$('#pin').value='';checkResume()}else toast('رمز خاطئ')}
function expB(){const j=JSON.stringify({app:'noun-star-u13',v:1,date:new Date().toISOString(),h:hs(JSON.stringify(S)),data:S});
modal(`<h3>نسخة احتياطية</h3><p class="mut">${S.drills.length} تمرين · ${S.boards.length} لوحة · ${S.players.length} لاعب · ${S.sessions.length} حصة</p><textarea id="bk" rows="6" readonly>${esc(j)}</textarea><div class="row"><button class="bt" onclick="$('#bk').select();document.execCommand('copy');toast('تم النسخ')">نسخ النص</button><button class="bt s" onclick="dlB()">تنزيل ملف</button><button class="bt s" onclick="closeM()">إغلاق</button></div><p class="mut">إن لم يبدأ التنزيل في متصفحك، انسخ النص واحفظه في ملف.</p>`)}
function dlB(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([$('#bk').value],{type:'application/json'}));a.download='noun-star-backup.json';a.click()}
function impB(){modal(`<h3>استعادة نسخة</h3><input type="file" accept=".json" onchange="const r=new FileReader();r.onload=()=>{$('#ib').value=r.result;chkB()};r.readAsText(this.files[0])"><textarea id="ib" rows="5" placeholder="أو ألصق النص هنا" oninput="chkB()"></textarea><div id="ibr"></div><div class="row"><button class="bt r" id="okB" disabled onclick="doB()">استبدال البيانات</button><button class="bt s" onclick="closeM()">إلغاء</button></div>`)}
let BK=null;
function chkB(){BK=null;try{const o=JSON.parse($('#ib').value);if(o.app!=='noun-star-u13'||o.v!==1)throw'ملف غير متوافق';const d=o.data;if(o.h&&o.h!==hs(JSON.stringify(d)))throw'فشل فحص السلامة: الملف معدّل أو تالف';for(const k of['drills','boards','players','sessions'])if(!Array.isArray(d[k]))throw'بنية تالفة: '+k;BK=d;$('#ibr').innerHTML=`<p class="ok">ملف صالح (${o.date.slice(0,10)}): ${d.drills.length} تمرين · ${d.boards.length} لوحة · ${d.players.length} لاعب · ${d.sessions.length} حصة. سيُستبدل كل ما لديك الآن.</p>`}catch(e){$('#ibr').innerHTML=`<p class="bad">ملف غير صالح: ${esc(typeof e==='string'?e:'تعذّرت قراءة JSON')}</p>`}$('#okB').disabled=!BK}
function doB(){if(!BK||!confirm('سيتم استبدال البيانات الحالية. متابعة؟'))return;const pin=S.settings;S=BK;S.settings=S.settings||pin;migrate();save();closeM();theme();toast('تمت الاستعادة');go('home')}
/* ---- init ---- */
(async()=>{const d=await load();if(d){S=d}else{seed()}migrate();save();theme();nav();go('home');if(S.settings.pin)$('#lock').style.display='flex';else checkResume()})();
